function initReliefAnimation(){const stage=document.querySelector('.uz-map-stage');if(!stage)return;const viewport=stage.closest('.uz-map-viewport');if(viewport&&matchMedia('(max-width: 767px)').matches)viewport.scrollLeft=Math.max(0,stage.clientWidth*939/1400-viewport.clientWidth/2);const paths=[...stage.querySelectorAll('.uz-link-draw')];paths.forEach(path=>{const len=path.getTotalLength();path.style.strokeDasharray=String(len);path.style.strokeDashoffset=String(len)});gsap.set(stage.querySelectorAll('.uz-link-flow'),{opacity:0});gsap.set(stage.querySelectorAll('.signal-node:not(.hub)'),{opacity:.18,scale:.45,transformOrigin:'center center'});const tl=gsap.timeline({scrollTrigger:{trigger:stage,start:'top 72%',once:true}});tl.to(paths,{strokeDashoffset:0,duration:1.7,stagger:.22,ease:'power2.inOut'}).to(stage.querySelectorAll('.signal-node:not(.hub)'),{opacity:1,scale:1,duration:.55,stagger:.11,ease:'back.out(1.7)'},'<.35').to(stage.querySelectorAll('.uz-link-flow'),{opacity:.8,duration:.5},'-=.25').call(()=>{gsap.to(stage.querySelectorAll('.uz-link-flow'),{strokeDashoffset:-90,duration:2.5,repeat:-1,ease:'none'});stage.querySelectorAll('.signal-node').forEach((node,i)=>{gsap.fromTo(node.querySelector('.halo'),{attr:{r:node.classList.contains('hub')?20:13},opacity:.65},{attr:{r:node.classList.contains('hub')?45:31},opacity:0,duration:2.2,delay:i*.22,repeat:-1,ease:'power1.out'})})})}

const serverLocalized=document.documentElement.dataset.serverLocalized==='true';let lang=serverLocalized?(location.pathname.match(/^\/(en|ru|uz)(?:\/|$)/)?.[1]||'en'):'en';const originals=new Map();document.querySelectorAll('[data-i18n]').forEach(el=>originals.set(el,el.innerHTML));const placeholderOriginals=new Map();document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>placeholderOriginals.set(el,el.getAttribute('placeholder')));
let scrubTween;
function buildScrub(){const el=document.getElementById('scrubText');if(scrubTween){scrubTween.scrollTrigger?.kill();scrubTween.kill();scrubTween=null}const words=el.textContent.trim().split(/\s+/);el.innerHTML=words.map((word,i)=>`<span class="word">${word}${i<words.length-1?' ':''}</span>`).join('');if(window.gsap&&window.ScrollTrigger&&!matchMedia('(prefers-reduced-motion: reduce)').matches){scrubTween=gsap.to(el.querySelectorAll('.word'),{opacity:1,stagger:.07,ease:'none',scrollTrigger:{trigger:el,start:'top 78%',end:'bottom 30%',scrub:1}})}}
function setLang(next){if(serverLocalized){const path=location.pathname.replace(/^\/(?:en|ru|uz)(?=\/|$)/,'');location.href='/'+next+(path||'/')+location.search+location.hash;return}lang=next;localStorage.setItem('s3-language',next);document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;el.innerHTML=lang==='ru'?(ru[key]??originals.get(el)):lang==='uz'?(uz[key]??originals.get(el)):originals.get(el)});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const key=el.dataset.i18nPlaceholder;el.setAttribute('placeholder',lang==='ru'?(ru[key]??placeholderOriginals.get(el)):lang==='uz'?(uz[key]??placeholderOriginals.get(el)):placeholderOriginals.get(el))});document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang))});document.title=lang==='ru'?'Strategic Security Systems | Системная интеграция':lang==='uz'?'Strategic Security Systems | Tizim integratsiyasi':'Strategic Security Systems | Systems Integration';document.querySelector('meta[name="description"]').content=lang==='ru'?ru.heroLead:lang==='uz'?uz.heroLead:originals.get(document.querySelector('[data-i18n="heroLead"]'));buildScrub();if(window.ScrollTrigger)ScrollTrigger.refresh();menuButton.setAttribute('aria-label',lang==='ru'?'Открыть меню':lang==='uz'?'Menyuni ochish':'Open menu');document.querySelector('.modal-close').setAttribute('aria-label',lang==='ru'?'Закрыть публикацию':lang==='uz'?'Maqolani yopish':'Close article');document.querySelectorAll('[data-article]').forEach(card=>card.setAttribute('aria-label',card.querySelector('h3')?.textContent||''))}
document.querySelectorAll('[data-lang]').forEach(btn=>btn.addEventListener('click',()=>setLang(btn.dataset.lang)));
const menuButton=document.querySelector('.menu-button'),mobileMenu=document.querySelector('.mobile-menu');function closeMenu(){document.body.classList.remove('menu-open');menuButton.setAttribute('aria-expanded','false');mobileMenu.setAttribute('aria-hidden','true')}menuButton.addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');menuButton.setAttribute('aria-expanded',String(open));mobileMenu.setAttribute('aria-hidden',String(!open))});mobileMenu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
const modal=document.getElementById('articleModal');function openArticle(key){const item=lang==='uz'?uzArticles[key]:articles[key]?.[lang];if(!item)return;document.getElementById('articleKind').textContent=item.kind;document.getElementById('articleTitle').textContent=item.title;document.getElementById('articleBody').innerHTML=item.body;document.getElementById('articleSource').textContent=item.source;modal.showModal();document.body.classList.add('modal-open')}function closeArticle(){modal.close();document.body.classList.remove('modal-open')}document.querySelectorAll('[data-article]').forEach(card=>{card.addEventListener('click',()=>openArticle(card.dataset.article));card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openArticle(card.dataset.article)}})});modal.querySelector('.modal-close').addEventListener('click',closeArticle);modal.addEventListener('click',e=>{if(e.target===modal)closeArticle()});modal.addEventListener('close',()=>document.body.classList.remove('modal-open'));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
if(window.gsap&&window.ScrollTrigger)gsap.registerPlugin(ScrollTrigger);if(serverLocalized){document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang))});buildScrub()}else setLang(['en','ru','uz'].includes(localStorage.getItem('s3-language'))?localStorage.getItem('s3-language'):'en');document.body.classList.add('js-ready');
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target)}}),{threshold:.08,rootMargin:'0px 0px -20px 0px'});document.querySelectorAll('[data-reveal]').forEach(el=>observer.observe(el));
if(window.gsap&&window.ScrollTrigger&&!matchMedia('(prefers-reduced-motion: reduce)').matches){gsap.registerPlugin(ScrollTrigger);const mm=gsap.matchMedia();mm.add('(min-width: 768px)',()=>{gsap.from('.hero-copy > *',{y:55,opacity:0,duration:1.15,stagger:.11,ease:'power3.out',delay:.1});gsap.from('.hero-image img',{scale:1.13,duration:1.8,ease:'power2.out'});ScrollTrigger.create({trigger:'.story-layout',pin:'.story-sticky',start:'top top+=95',end:'bottom bottom',pinSpacing:false,anticipatePin:1});gsap.utils.toArray('.story-panel').forEach(panel=>{gsap.timeline({scrollTrigger:{trigger:panel,start:'top bottom',end:'bottom top',scrub:.8}}).fromTo(panel.querySelector('img'),{scale:.84,opacity:.35},{scale:1,opacity:1,duration:.5,ease:'none'}).to(panel.querySelector('img'),{scale:1.06,opacity:.28,duration:.5,ease:'none'})})});initReliefAnimation();gsap.to('.marquee',{xPercent:-50,duration:30,repeat:-1,ease:'none'});document.querySelector('.marquee').style.animation='none';buildScrub();ScrollTrigger.refresh();const mapViewport=document.querySelector('.uz-map-viewport');if(innerWidth<768&&mapViewport)mapViewport.scrollLeft=Math.max(0,mapViewport.querySelector('.uz-map-stage').clientWidth*939/1400-mapViewport.clientWidth/2)}
